1	package org.springframework.samples.petclinic.mapper;
2	
3	/**
4	 * Derives an owner's region, either from a postcode or from the region-and-hash
5	 * {@code customerCode}, plus the legacy city-to-region lookup.
6	 *
7	 * <p>{@link #region(String)} maps a postcode to its region by the fixed ranges
8	 * (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099); this is the region embedded in
9	 * an owner's {@code '<REGION>-<HASH8>'} customer code. {@link #locality(String)}
10	 * reads an owner's locality straight back out of that customer code (its
11	 * {@code <REGION>} component), so the locality and the identity always agree.
12	 * The city-to-region table (Sydney -> NSW, Melbourne -> VIC, Brisbane -> QLD)
13	 * remains available via {@link #localityForCity(String)} for postcode validation.
14	 *
15	 * <p>Kept as a standalone helper (rather than a method on {@link OwnerMapper})
16	 * so MapStruct does not mistake it for a generic {@code String -> String}
17	 * mapping method and apply it to unrelated fields; the mapper references it only
18	 * through an explicit expression.
19	 */
20	public final class LocalityDeriver {
21	
22	    private LocalityDeriver() {
23	    }
24	
25	    /**
26	     * Returns the region code derived from the postcode: the region whose fixed inclusive range
27	     * contains the 4-digit postcode (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099), or
28	     * {@code "UNKNOWN"} when the postcode is absent, not a 4-digit value, or in no known range.
29	     * This is the {@code <REGION>} component embedded in a new owner's customer code.
30	     */
31	    public static String region(String postcode) {
32	        String byPostcode = regionForPostcode(postcode);
33	        return byPostcode != null ? byPostcode : "UNKNOWN";
34	    }
35	
36	    /**
37	     * Returns an owner's locality: the {@code <REGION>} component of the {@code '<REGION>-<HASH8>'}
38	     * customer code (the text before the first {@code '-'}). Returns {@code "UNKNOWN"} when the
39	     * customer code is {@code null}/blank or carries no region component.
40	     */
41	    public static String locality(String customerCode) {
42	        if (customerCode == null || customerCode.isBlank()) {
43	            return "UNKNOWN";
44	        }
45	        int dash = customerCode.indexOf('-');
46	        String region = dash < 0 ? customerCode : customerCode.substring(0, dash);
47	        return region.isBlank() ? "UNKNOWN" : region;
48	    }
49	
50	    /**
51	     * Returns the canonical region string for the given city, or {@code "UNKNOWN"}
52	     * when the city is {@code null} or not in the fixed table.
53	     */
54	    public static String localityForCity(String city) {
55	        if (city == null) {
56	            return "UNKNOWN";
57	        }
58	        return switch (city) {
59	            case "Sydney" -> "NSW";
60	            case "Melbourne" -> "VIC";
61	            case "Brisbane" -> "QLD";
62	            default -> "UNKNOWN";
63	        };
64	    }
65	
66	    /**
67	     * Returns the region whose fixed inclusive range contains the given 4-digit postcode
68	     * (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099), or {@code null} when the postcode is
69	     * absent, not a 4-digit value, or in no known range.
70	     */
71	    private static String regionForPostcode(String postcode) {
72	        if (postcode == null || !postcode.matches("[0-9]{4}")) {
73	            return null;
74	        }
75	        int value = Integer.parseInt(postcode);
76	        if (value >= 2000 && value <= 2099) {
77	            return "NSW";
78	        }
79	        if (value >= 3000 && value <= 3099) {
80	            return "VIC";
81	        }
82	        if (value >= 4000 && value <= 4099) {
83	            return "QLD";
84	        }
85	        return null;
86	    }
87	}
